        <button :class="{active:activeCard==='A'}" @click="activeCard='A'"><b>A</b><span>&#x6865;&#x6881;&#x57FA;&#x672C;&#x72B6;&#x51B5;&#x5361;&#x7247;</span><small>&#x6BCF;&#x5EA7;&#x6865;&#x6881;&#x4E00;&#x4EFD;</small></button>
        <button :class="{active:activeCard==='B'}" @click="activeCard='B'"><b>B</b><span>&#x6865;&#x6881;&#x521D;&#x59CB;&#x68C0;&#x67E5;&#x8BB0;&#x5F55;&#x8868;</span><small>&#x6BCF;&#x5EA7;&#x6865;&#x6881;&#x4E00;&#x4EFD;</small></button>
        <button :class="{active:activeCard==='C'}" @click="activeCard='C'"><b>C</b><span>&#x6865;&#x6881;&#x5B9A;&#x671F;&#x68C0;&#x67E5;&#x8868;</span><small>{{ data.periodicInspections.length }} &#x4EFD;&#x5386;&#x53F2;&#x8BB0;&#x5F55;</small></button>
        <button :class="{active:activeCard==='S'}" @click="activeCard='S'"><b>Σ</b><span>检查结果汇总</span><small>跨期趋势与对比</small></button>
      </div>

      <article v-show="activeCard==='A'" class="condition-card">
        <div class="document-heading"><div class="doc-badge">A</div><div><p>JTG 5120—2021 桥梁档案</p><h1>桥梁基本状况卡片</h1><span>BRIDGE BASIC CONDITION RECORD</span></div><div class="doc-code"><small>桥梁编号</small><b>{{ bridge.bridge_code }}</b><small>建档日期 {{ bridge.archive_date || bridge.card_date || '—' }}</small></div></div>

        <CardSection code="A" title="桥梁所处行政区划" icon="location" :items="[['行政区划代码',bridge.administrative_code],['桥梁详细地址',bridge.location_address],['高德坐标',coordinate]]" />
        <CardSection code="B" title="行政识别数据" icon="identity" :items="identityItems" />
        <CardSection code="C" title="桥梁技术指标" icon="technical" :items="technicalItems" />

        <section class="card-section structure-section">
