          <div class="structure-summary"><div><small>跨径组合</small><b>{{ show(bridge.span_combination) }}</b></div><div><small>结构体系</small><b>{{ show(bridge.structural_system) }}</b></div><div><small>具体部件总数</small><b>{{ data.components.length }}</b></div></div>
          <BridgeStructureDetails :details="data.structureDetails"/>
          <BridgeDynamicMatrix :components="data.components"/>
        </section>

        <section class="card-section"><SectionTitle code="E" title="桥梁档案资料" subtitle="设计、施工、验收及历次检查文件完整性"/><el-table :data="data.archives" border size="small" class="card-table"><el-table-column prop="archive_item_name" label="档案资料项"/><el-table-column prop="completeness_status" label="齐全状态" width="120"><template #default="{row}"><el-tag :type="row.completeness_status==='全'?'success':row.completeness_status==='无'?'danger':'warning'" effect="plain">{{ row.completeness_status || '未填写' }}</el-tag></template></el-table-column><el-table-column prop="description" label="说明"/></el-table></section>
        <section class="card-section"><SectionTitle code="F" title="桥梁检测评定历史" subtitle="历次检测结论与下次检测建议"/><el-table :data="data.evaluations" border size="small" class="card-table"><el-table-column prop="evaluation_date" label="评定时间" width="130"/><el-table-column prop="check_category_name" label="检测类别" width="130"/><el-table-column prop="rating_result" label="评定结果"/><el-table-column prop="special_conclusion" label="特殊检查结论"/><el-table-column prop="next_check_date" label="下次检测时间" width="130"/></el-table></section>
        <CardSection code="H" title="需要说明的事项" icon="notes" :items="[['说明',bridge.notes],['公路管理机构',bridge.road_management_org],['管养单位',bridge.management_unit],['桥梁工程师',bridge.bridge_engineer],['填卡人',bridge.card_filler],['填卡日期',bridge.card_date]]" />

        <section class="card-section photo-section">
