          <div class="photo-category-grid"><article v-for="group in photoGroups" :key="group.code" class="photo-category"><div class="photo-category-head"><div><b>{{ group.name }}</b><span>{{ group.files.length }} 张</span></div><el-button v-if="canUpload" text type="primary" @click="openUpload(group.code)">上传</el-button></div><template v-if="currentPhoto(group)"><figure @click="previewUrl=fileUrl(currentPhoto(group))"><img :src="fileUrl(currentPhoto(group))" :alt="currentPhoto(group).file_description"><figcaption><b>{{ currentPhoto(group).file_description||group.name }}</b><span>{{ currentPhoto(group).file_name }} · {{ currentPhoto(group).upload_time }}</span></figcaption></figure><div v-if="group.files.length>1" class="photo-switch"><el-button circle size="small" @click="stepPhoto(group,-1)">‹</el-button><span>{{ (photoIndex[group.code]||0)+1 }} / {{ group.files.length }}</span><el-button circle size="small" @click="stepPhoto(group,1)">›</el-button></div></template><div v-else class="empty-category"><Images :size="28"/><span>暂无图片</span></div></article></div>
        </section>
        <footer class="card-footer"><span>桥梁工程师：{{ bridge.bridge_engineer || '—' }}</span><span>填卡人：{{ bridge.card_filler || '—' }}</span><span>填卡日期：{{ bridge.card_date || '—' }}</span></footer>
      </article>
      <BridgeInitialCard v-show="activeCard==='B'" :record="data.initialInspections?.[0]" :items="data.initialItems" :component-items="data.initialComponentItems"/>
      <BridgePeriodicCards v-show="activeCard==='C'" :periods="data.periodicInspections"/>
      <BridgeInspectionSummary v-if="activeCard==='S'" :summary="data.inspectionSummary"/>
    </template>

    <el-dialog v-model="uploadDialog" title="上传桥梁照片" width="560px" class="photo-upload-dialog">
