      <el-form label-position="top"><el-form-item label="照片分类"><el-input :model-value="categoryName(uploadCategory)" disabled/></el-form-item><el-form-item label="图片说明"><el-input v-model="photoDescription"/></el-form-item><el-form-item label="选择照片"><el-upload v-model:file-list="uploadFiles" drag multiple :auto-upload="false" accept=".jpg,.jpeg,.png,image/jpeg,image/png" :limit="8"><el-icon class="el-icon--upload"><Upload/></el-icon><div class="el-upload__text">拖拽照片到此处，或<em>点击选择</em></div><template #tip><div class="el-upload__tip">支持 JPG、JPEG、PNG，单张不超过 10MB；一次最多 8 张。</div></template></el-upload></el-form-item></el-form>
      <template #footer><el-button @click="uploadDialog=false">取消</el-button><el-button type="primary" :loading="uploading" :disabled="!uploadFiles.length" @click="submitPhotos">上传 {{ uploadFiles.length ? `（${uploadFiles.length}张）` : '' }}</el-button></template>
    </el-dialog>
