<script setup>
import { computed, defineComponent, h, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { Building2, Images, MapPin, PanelsTopLeft, Ruler, Upload } from 'lucide-vue-next'
import http from '../api/http'
import BridgeDynamicMatrix from '../components/BridgeDynamicMatrix.vue'
import BridgeInitialCard from '../components/BridgeInitialCard.vue'
import BridgePeriodicCards from '../components/BridgePeriodicCards.vue'
import BridgeInspectionSummary from '../components/BridgeInspectionSummary.vue'
import BridgeStructureDetails from '../components/BridgeStructureDetails.vue'
import { useAuthStore } from '../stores/auth'

const SectionTitle=defineComponent({props:{code:String,title:String,subtitle:String},setup(props){return()=>h('div',{class:'section-title'},[h('span',props.code),h('div',[h('h3',props.title),h('p',props.subtitle)])])}})
const CardSection=defineComponent({props:{code:String,title:String,items:Array},setup(props){return()=>h('section',{class:'card-section'},[h(SectionTitle,{code:props.code,title:props.title}),h('div',{class:'card-grid'},props.items.map(([label,value])=>h('div',{class:'card-cell'},[h('b',label),h('span',value===null||value===undefined||value===''?'—':String(value))])))])}})
const route=useRoute(),router=useRouter(),auth=useAuthStore(),loading=ref(false),uploading=ref(false),generatingPdf=ref(false),uploadDialog=ref(false),uploadFiles=ref([]),photoDescription=ref(''),uploadCategory=ref('overall'),photoIndex=reactive({}),previewUrl=ref(''),activeCard=ref('A'),data=ref({bridge:null,components:[],archives:[],evaluations:[],attachments:[],structureDetails:{spans:[],structures:[],cables:[]},inspectionSummary:{},initialInspections:[],initialItems:[],initialComponentItems:[],periodicInspections:[]})
const photoTypes=[{code:'overall',name:'桥梁总体照片'},{code:'front',name:'桥梁正面照片'},{code:'left_elevation',name:'桥梁左侧立面照片'},{code:'right_elevation',name:'桥梁右侧立面照片'},{code:'deck',name:'桥面照片'},{code:'pier_foundation',name:'桥墩及基础照片'},{code:'other',name:'其他桥梁照片'}]
const bridge=computed(()=>data.value.bridge),canUpload=computed(()=>['admin','engineer','inspector'].includes(auth.role)),canEdit=computed(()=>['admin','engineer'].includes(auth.role)),canGenerate=canEdit,show=(value,suffix='')=>value===null||value===undefined||value===''?'—':`${value}${suffix}`
const coordinate=computed(()=>bridge.value?.longitude&&bridge.value?.latitude?`${bridge.value.longitude}, ${bridge.value.latitude}`:'—')
const imageAttachments=computed(()=>data.value.attachments.filter(x=>/image|jpg|jpeg|png/i.test(`${x.file_type||''}${x.file_name||''}`)))
const photoGroups=computed(()=>photoTypes.map(item=>({...item,files:imageAttachments.value.filter(file=>(file.photo_category||'overall')===item.code)})))
const fileUrl=file=>`/api/files/view?path=${encodeURIComponent(file.storage_path)}`,coverUrl=computed(()=>imageAttachments.value.length?fileUrl(imageAttachments.value[0]):'')
const pierComponents=computed(()=>data.value.components.filter(x=>x.component_serial?.includes('#')&&/桥墩|桥桩|墩柱|基础/.test(`${x.component_name}${x.component_serial}${x.location_desc||''}`)))
const identityItems=computed(()=>[['路线编号',bridge.value.route_code],['路线名称',bridge.value.route_name],['路线等级',bridge.value.route_grade],['桥梁编号',bridge.value.bridge_code],['桥梁名称',bridge.value.bridge_name],['桥位桩号',bridge.value.pile_number],['功能类型',bridge.value.function_type],['被跨越道路（通道）名称',bridge.value.crossed_road_name],['被跨越道路（通道）桩号',bridge.value.crossed_road_pile],['设计荷载',bridge.value.design_load],['桥梁坡度',bridge.value.bridge_slope],['桥梁平曲线半径',bridge.value.curve_radius],['建成年份',bridge.value.built_year],['设计单位',bridge.value.design_unit],['施工单位',bridge.value.construction_unit],['监理单位',bridge.value.supervision_unit],['业主单位',bridge.value.owner_unit],['管养单位',bridge.value.management_unit]])
const technicalItems=computed(()=>[['桥梁全长（m）',bridge.value.bridge_length],['桥面总宽（m）',bridge.value.deck_width],['车道宽度（m）',bridge.value.lane_width],['人行道宽度（m）',bridge.value.sidewalk_width],['护栏或防撞墙高度（m）',bridge.value.barrier_height],['中央分隔带宽度（m）',bridge.value.median_width],['桥面标准净空',bridge.value.standard_clearance],['桥面实际净空',bridge.value.actual_clearance],['桥下通航等级及标准净空',bridge.value.navigation_standard],['桥下实际净空',bridge.value.navigation_actual],['引道总宽（m）',bridge.value.approach_width],['引道线形或曲线半径',bridge.value.approach_alignment],['设计洪水频率及其水位',bridge.value.design_flood],['历史洪水位',bridge.value.historical_flood],['地震动峰值加速度系数',bridge.value.seismic_coefficient]])
function printCard(){window.print()}
function categoryName(code){return photoTypes.find(x=>x.code===code)?.name||'桥梁照片'}
function openUpload(code){uploadCategory.value=code;photoDescription.value=categoryName(code);uploadFiles.value=[];uploadDialog.value=true}
function currentPhoto(group){return group.files[photoIndex[group.code]||0]}
function stepPhoto(group,step){const current=photoIndex[group.code]||0;photoIndex[group.code]=(current+step+group.files.length)%group.files.length}
async function generateCardPdf(){generatingPdf.value=true;try{const report=await http.post(`/reports/bridge-card/${bridge.value.bridge_code}`,{});await downloadReport(report);ElMessage.success('桥梁基本状况卡片 PDF 已生成')}finally{generatingPdf.value=false}}
async function downloadReport(report){const response=await fetch(`/api/reports/${report.report_id}/download`,{headers:{Authorization:`Bearer ${localStorage.getItem('bridge_token')}`}});if(!response.ok)throw new Error('PDF 下载失败');const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`${report.report_id}.pdf`;link.click();URL.revokeObjectURL(url)}
async function load(){loading.value=true;try{data.value=await http.get(`/bridge-profiles/${route.params.bridgeCode}`)}finally{loading.value=false}}
async function submitPhotos(){uploading.value=true;try{for(const item of uploadFiles.value){if(!item.raw)continue;if(item.raw.size>10*1024*1024)throw new Error(`${item.name} 超过10MB`);const form=new FormData();form.append('file',item.raw);form.append('description',photoDescription.value);form.append('category',uploadCategory.value);await http.post(`/bridge-profiles/${bridge.value.bridge_code}/photos`,form)}ElMessage.success('桥梁照片上传成功');uploadFiles.value=[];uploadDialog.value=false;await load()}catch(error){ElMessage.error(error.message||'照片上传失败')}finally{uploading.value=false}}
onMounted(load)
</script>

